{"applies":"function applies(input){return Array.isArray(input.events)&&input.events.length<=48&&input.config&&Number.isInteger(input.config.keep)&&input.config.keep>=1}","assumptions":"Inputs satisfy the stated numeric, event, and capacity constraints. State is internally represented as a snapshot array. Damage mutates only data and never the stored checksum.","explanation":"The conditional rule is: retain snapshots in insertion order, replace an existing ID before appending it, cap retention to the newest keep entries, and restore the newest retained snapshot whose stored checksum matches its recomputed checksum. A counterexample to choosing the newest snapshot unconditionally is p1: damaged b must be skipped so a is restored.","holds":"function holds(input,output){if(!Array.isArray(output)||output.length!==input.events.length)return false; for(const x of output){if(!x||!Array.isArray(x.retained)||!Object.prototype.hasOwnProperty.call(x,'data')||!Object.prototype.hasOwnProperty.call(x,'chosen'))return false} return true}","mapping":"config.keep maps to retention capacity; each snapshot maps to {id,data,checksum}; event operations map to ordered state transitions; restore maps to reverse validation and copying.","program":"function solve({config,state,event}) {
  let s = Array.isArray(state) ? state : [];
  const copy = a => a.slice();
  const sum = a => { let n=0; for(let i=0;i<a.length;i++) n=(n+(i+1)*a[i])%251; return n; };
  const type = event && event.type;
  if(type === 'save') {
    const id=event.id;
    let k=s.findIndex(x=>x.id===id);
    if(k>=0) s.splice(k,1);
    s.push({id:id,data:copy(event.data),checksum:event.checksum});
    while(s.length>config.keep) s.shift();
  } else if(type === 'damage') {
    const x=s.find(x=>x.id===event.id);
    if(x && Number.isInteger(event.index) && event.index>=0 && event.index<x.data.length) x.data[event.index]=event.value;
  } else if(type === 'drop') {
    const k=s.findIndex(x=>x.id===event.id);
    if(k>=0) s.splice(k,1);
  } else if(type === 'restore') {}
  let data=null, chosen=null;
  if(type === 'restore') {
    for(let i=s.length-1;i>=0;i--) if(sum(s[i].data)===s[i].checksum){data=copy(s[i].data);chosen=s[i].id;break;}
  }
  return {state:s,output:{data:data,chosen:chosen,retained:s.map(x=>x.id)}};
}"}
